ss_alu.vhdl:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
entity ss_alu is
  generic (WIDTH:positive range 1 to 64:=8; SIGNED_MODE:natural range 0 to 1:=0);
  port (clk,rst,en,start:in std_logic; opcode:in std_logic_vector(2 downto 0);
    a,b:in std_logic_vector(WIDTH-1 downto 0); cin:in std_logic;
    y,result_hi:out std_logic_vector(WIDTH-1 downto 0);
    busy,done,valid,carry,borrow,overflow,divide_by_zero,zero,negative,invalid_op:out std_logic);
end entity;
architecture rtl of ss_alu is
  type words is array(0 to 7) of std_logic_vector(WIDTH-1 downto 0);
  signal values:words;
  signal add_carry,add_overflow,add_zero,add_negative:std_logic;
  signal sub_borrow,sub_overflow,sub_zero,sub_negative:std_logic;
  signal mul_hi:std_logic_vector(WIDTH-1 downto 0);
  signal mul_overflow,mul_zero,mul_negative:std_logic;
  signal div_a,div_b,div_q,div_r:std_logic_vector(WIDTH-1 downto 0):=(others=>'0');
  signal div_start,div_done,div_valid,div_error,div_overflow,div_zero,div_negative:std_logic:='0';
  signal active,event_done,result_valid,flag_carry,flag_borrow,flag_overflow,flag_divide,flag_negative,flag_invalid:std_logic:='0';
  signal flag_zero:std_logic:='1';
  signal result_value,result_upper:std_logic_vector(WIDTH-1 downto 0):=(others=>'0');
begin
  addition:entity work.ss_add_sub generic map(WIDTH=>WIDTH,SIGNED_MODE=>SIGNED_MODE,SUBTRACT=>0)
    port map(a=>a,b=>b,cin=>cin,y=>values(0),carry=>add_carry,borrow=>open,overflow=>add_overflow,zero=>add_zero,negative=>add_negative);
  subtraction:entity work.ss_add_sub generic map(WIDTH=>WIDTH,SIGNED_MODE=>SIGNED_MODE,SUBTRACT=>1)
    port map(a=>a,b=>b,cin=>cin,y=>values(1),carry=>open,borrow=>sub_borrow,overflow=>sub_overflow,zero=>sub_zero,negative=>sub_negative);
  multiplication:entity work.ss_multiply generic map(WIDTH=>WIDTH,SIGNED_MODE=>SIGNED_MODE)
    port map(a=>a,b=>b,result_lo=>values(2),result_hi=>mul_hi,overflow=>mul_overflow,zero=>mul_zero,negative=>mul_negative);
  division:entity work.ss_divide generic map(WIDTH=>WIDTH,SIGNED_MODE=>SIGNED_MODE)
    port map(clk=>clk,rst=>rst,en=>en,start=>div_start,a=>div_a,b=>div_b,quotient=>div_q,remainder=>div_r,
      busy=>open,done=>div_done,valid=>div_valid,divide_by_zero=>div_error,overflow=>div_overflow,zero=>div_zero,negative=>div_negative);
  values(3)<=div_q;
  logic_and:entity work.ss_bitwise generic map(WIDTH=>WIDTH,OPERATION=>0) port map(a=>a,b=>b,y=>values(4),zero=>open);
  logic_or:entity work.ss_bitwise generic map(WIDTH=>WIDTH,OPERATION=>1) port map(a=>a,b=>b,y=>values(5),zero=>open);
  logic_xor:entity work.ss_bitwise generic map(WIDTH=>WIDTH,OPERATION=>2) port map(a=>a,b=>b,y=>values(6),zero=>open);
  logic_not:entity work.ss_bitwise generic map(WIDTH=>WIDTH,OPERATION=>6) port map(a=>a,b=>b,y=>values(7),zero=>open);
  y<=result_value; result_hi<=result_upper; busy<=active; done<=event_done; valid<=result_valid;
  carry<=flag_carry; borrow<=flag_borrow; overflow<=flag_overflow; divide_by_zero<=flag_divide;
  zero<=flag_zero; negative<=flag_negative; invalid_op<=flag_invalid;
  process(clk)
    variable operation:natural range 0 to 7;
  begin
    if rising_edge(clk) then
      event_done<='0'; div_start<='0';
      if rst='1' then
        active<='0'; result_valid<='0'; result_value<=(others=>'0'); result_upper<=(others=>'0');
        div_a<=(others=>'0'); div_b<=(others=>'0');
        flag_carry<='0'; flag_borrow<='0'; flag_overflow<='0'; flag_divide<='0'; flag_negative<='0'; flag_invalid<='0'; flag_zero<='1';
      elsif active='1' then
        if div_done='1' then
          active<='0'; event_done<='1'; result_valid<=div_valid; result_value<=div_q; result_upper<=div_r;
          flag_overflow<=div_overflow; flag_divide<=div_error; flag_zero<=div_zero; flag_negative<=div_negative;
        end if;
      elsif start='1' and en='1' then
        result_valid<='0'; flag_carry<='0'; flag_borrow<='0'; flag_overflow<='0'; flag_divide<='0'; flag_invalid<='0';
        if is_x(opcode) then flag_invalid<='1'; event_done<='1';
        else
          operation:=to_integer(unsigned(opcode));
          if operation=3 then div_a<=a; div_b<=b; div_start<='1'; active<='1';
          else
            result_value<=values(operation); result_upper<=(others=>'0'); result_valid<='1'; event_done<='1';
            flag_zero<='0'; if unsigned(values(operation))=0 then flag_zero<='1'; end if;
            flag_negative<='0'; if SIGNED_MODE=1 then flag_negative<=values(operation)(WIDTH-1); end if;
            case operation is
              when 0 => flag_carry<=add_carry; flag_overflow<=add_overflow; flag_zero<=add_zero; flag_negative<=add_negative;
              when 1 => flag_borrow<=sub_borrow; flag_overflow<=sub_overflow; flag_zero<=sub_zero; flag_negative<=sub_negative;
              when 2 => result_upper<=mul_hi; flag_overflow<=mul_overflow; flag_zero<=mul_zero; flag_negative<=mul_negative;
              when others => null;
            end case;
          end if;
        end if;
      end if;
    end if;
  end process;
end architecture;

ss_add_sub.vhdl:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
entity ss_add_sub is
  generic (WIDTH:positive range 1 to 64:=8; SUBTRACT:natural range 0 to 1:=0; SIGNED_MODE:natural range 0 to 1:=0);
  port (a,b:in std_logic_vector(WIDTH-1 downto 0); cin:in std_logic;
    y:out std_logic_vector(WIDTH-1 downto 0); carry,borrow,overflow,zero,negative:out std_logic);
end entity;
architecture rtl of ss_add_sub is begin
  process(a,b,cin)
    variable u:unsigned(WIDTH downto 0);
    variable s:signed(WIDTH+1 downto 0);
    variable result:std_logic_vector(WIDTH-1 downto 0);
  begin
    carry<='0'; borrow<='0'; overflow<='0'; negative<='0';
    if SUBTRACT=0 then
      u:=resize(unsigned(a),WIDTH+1)+resize(unsigned(b),WIDTH+1);
      s:=resize(signed(a),WIDTH+2)+resize(signed(b),WIDTH+2);
      if cin='1' then u:=u+1; s:=s+1; end if;
      carry<=u(WIDTH);
    else
      u:=resize(unsigned(a),WIDTH+1)-resize(unsigned(b),WIDTH+1);
      s:=resize(signed(a),WIDTH+2)-resize(signed(b),WIDTH+2);
      if cin='1' then u:=u-1; s:=s-1; end if;
      borrow<=u(WIDTH);
    end if;
    result:=std_logic_vector(u(WIDTH-1 downto 0)); y<=result;
    if SIGNED_MODE=1 then
      negative<=result(WIDTH-1);
      if s/=resize(signed(result),WIDTH+2) then overflow<='1'; end if;
    end if;
    zero<='0'; if unsigned(result)=0 then zero<='1'; end if;
  end process;
end architecture;

ss_multiply.vhdl:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
entity ss_multiply is
  generic (WIDTH:positive range 1 to 64:=8; SIGNED_MODE:natural range 0 to 1:=0);
  port (a,b:in std_logic_vector(WIDTH-1 downto 0);
    result_lo,result_hi:out std_logic_vector(WIDTH-1 downto 0); overflow,zero,negative:out std_logic);
end entity;
architecture rtl of ss_multiply is begin
  process(a,b)
    variable product:std_logic_vector(2*WIDTH-1 downto 0);
  begin
    overflow<='0'; negative<='0';
    if SIGNED_MODE=1 then
      product:=std_logic_vector(signed(a)*signed(b)); negative<=product(2*WIDTH-1);
      if signed(product)/=resize(signed(product(WIDTH-1 downto 0)),2*WIDTH) then overflow<='1'; end if;
    else
      product:=std_logic_vector(unsigned(a)*unsigned(b));
      if unsigned(product(2*WIDTH-1 downto WIDTH))/=0 then overflow<='1'; end if;
    end if;
    result_lo<=product(WIDTH-1 downto 0); result_hi<=product(2*WIDTH-1 downto WIDTH);
    zero<='0'; if unsigned(product)=0 then zero<='1'; end if;
  end process;
end architecture;

ss_divide.vhdl:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
entity ss_divide is
  generic (WIDTH:positive range 1 to 64:=8; SIGNED_MODE:natural range 0 to 1:=0);
  port (clk,rst,en,start:in std_logic; a,b:in std_logic_vector(WIDTH-1 downto 0);
    quotient,remainder:out std_logic_vector(WIDTH-1 downto 0);
    busy,done,valid,divide_by_zero,overflow,zero,negative:out std_logic);
end entity;
architecture rtl of ss_divide is
  signal active,event_done,result_valid,error_zero,error_overflow:std_logic:='0';
  signal q_work,divisor,q_result,r_result:unsigned(WIDTH-1 downto 0):=(others=>'0');
  signal r_work:unsigned(WIDTH downto 0):=(others=>'0');
  signal negate_q,negate_r:std_logic:='0';
  signal step:natural range 0 to WIDTH-1:=0;
begin
  quotient<=std_logic_vector(q_result); remainder<=std_logic_vector(r_result);
  busy<=active; done<=event_done; valid<=result_valid; divide_by_zero<=error_zero; overflow<=error_overflow;
  zero<='1' when q_result=0 else '0'; negative<=q_result(WIDTH-1) when SIGNED_MODE=1 else '0';
  process(clk)
    variable next_r:unsigned(WIDTH downto 0);
    variable next_q,final_q,final_r,mag_a,mag_b,min_value:unsigned(WIDTH-1 downto 0);
  begin
    if rising_edge(clk) then
      event_done<='0';
      if rst='1' then
        active<='0'; result_valid<='0'; error_zero<='0'; error_overflow<='0';
        q_work<=(others=>'0'); divisor<=(others=>'0'); r_work<=(others=>'0');
        q_result<=(others=>'0'); r_result<=(others=>'0'); negate_q<='0'; negate_r<='0'; step<=0;
      elsif start='1' and active='0' then
        result_valid<='0'; error_zero<='0'; error_overflow<='0';
        mag_a:=unsigned(a); mag_b:=unsigned(b); min_value:=(others=>'0'); min_value(WIDTH-1):='1';
        if unsigned(b)=0 then
          q_result<=(others=>'0'); r_result<=unsigned(a); error_zero<='1'; event_done<='1';
        elsif SIGNED_MODE=1 and unsigned(a)=min_value and signed(b)=-1 then
          q_result<=unsigned(a); r_result<=(others=>'0'); error_overflow<='1'; event_done<='1';
        else
          negate_q<='0'; negate_r<='0';
          if SIGNED_MODE=1 then
            negate_q<=a(WIDTH-1) xor b(WIDTH-1); negate_r<=a(WIDTH-1);
            if a(WIDTH-1)='1' then mag_a:=unsigned(-signed(a)); end if;
            if b(WIDTH-1)='1' then mag_b:=unsigned(-signed(b)); end if;
          end if;
          q_work<=mag_a; divisor<=mag_b; r_work<=(others=>'0'); step<=0; active<='1';
        end if;
      elsif active='1' and en='1' then
        next_r:=shift_left(r_work,1); next_r(0):=q_work(WIDTH-1); next_q:=shift_left(q_work,1);
        if next_r>=resize(divisor,WIDTH+1) then next_r:=next_r-resize(divisor,WIDTH+1); next_q(0):='1'; end if;
        q_work<=next_q; r_work<=next_r;
        if step=WIDTH-1 then
          final_q:=next_q; final_r:=next_r(WIDTH-1 downto 0);
          if negate_q='1' then final_q:=unsigned(-signed(final_q)); end if;
          if negate_r='1' then final_r:=unsigned(-signed(final_r)); end if;
          q_result<=final_q; r_result<=final_r; active<='0'; event_done<='1'; result_valid<='1';
        else step<=step+1; end if;
      end if;
    end if;
  end process;
end architecture;

ss_bitwise.vhdl:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
entity ss_bitwise is
  generic (WIDTH:positive range 1 to 64:=8; OPERATION:natural range 0 to 6:=0);
  port (a,b:in std_logic_vector(WIDTH-1 downto 0); y:out std_logic_vector(WIDTH-1 downto 0); zero:out std_logic);
end entity;
architecture rtl of ss_bitwise is begin
  process(a,b)
    variable result:std_logic_vector(WIDTH-1 downto 0);
  begin
    case OPERATION is
      when 0=>result:=a and b; when 1=>result:=a or b; when 2=>result:=a xor b;
      when 3=>result:=a nand b; when 4=>result:=a nor b; when 5=>result:=a xnor b;
      when others=>result:=not a;
    end case;
    y<=result; zero<='0'; if unsigned(result)=0 then zero<='1'; end if;
  end process;
end architecture;
